# Amend two unfinished local authored cases, before finalization, to expose the caster's real departure.
def insert_caster_exit(c):
    base=copy.deepcopy(c['timeline'][1]['after'])
    after=copy.deepcopy(base);after['time']=1.2;after['actors']['C']['position']=[-10,0,0];after['actors']['C']['movementSpent']=10
    ev={'index':2,'time':1.2,'description':'Caster spends10 actual movement feet to leave all burning support before its next START',
        'before':base,'scheduledBudgetProcessing':[],'detail':{'clearSupportedPath':True,'noAdditionalAction':True},
        'resolution':{'movementSpent':10,'outsidePatch':True},'after':after}
    for e in c['timeline'][2:]:
        for key in ['before','after']:
            a=e[key]['actors']['C'];a['position']=[-10,0,0]
            if a['previousSTART']==0:a['movementSpent']=10
        if e is c['timeline'][2]:e['before']=copy.deepcopy(after)
    c['timeline'].insert(2,ev)
    for i,e in enumerate(c['timeline']):e['index']=i
    c['expectedFinalState']=copy.deepcopy(c['timeline'][-1]['after'])
for cc in cases:
    if cc['spellId']=='pyroclasm':insert_caster_exit(cc)
cases[3]['geometry'].update(upperPlatformBox={'min':[19.5,-5,14.5],'max':[20.5,5,15]},initialBurstWitness=[18,0,16],
    explanation='Existing supported narrow platform; line from center[15,0,3] to target interior[18,0,16] misses its opaque slab. Upper face itself has no path from below, so no upper fire patch.')
